using System.ComponentModel.DataAnnotations; using dxpmt.Data; using dxpmt.Domain; using Microsoft.AspNetCore.Mvc; using Microsoft.AspNetCore.Mvc.RazorPages; using Microsoft.EntityFrameworkCore;
namespace dxpmt.Pages.Problems;
public sealed class CreateModel(ApplicationDbContext database):PageModel { [BindProperty] public InputModel Input{get;set;}=new(); public ImprovementCase Case{get;private set;}=null!; public List<WorkItem> WorkItems{get;private set;}=[]; public IReadOnlyList<string> Categories=>ProblemCategories.All; public async Task<IActionResult> OnGetAsync(int caseId){if(!await Load(caseId))return NotFound();return Page();} public async Task<IActionResult> OnPostAsync(int caseId){if(!await Load(caseId))return NotFound();if(!ProblemCategories.All.Contains(Input.Category))ModelState.AddModelError("Input.Category","分類を選択してください。");if(!CasePriorities.All.Contains(Input.Severity))ModelState.AddModelError("Input.Severity","重要度を選択してください。");if(!ProblemStatuses.All.Contains(Input.Status))ModelState.AddModelError("Input.Status","状態を選択してください。");if(!ModelState.IsValid)return Page();var now=DateTime.UtcNow;var seq=(await database.Problems.Where(x=>x.CaseId==caseId).MaxAsync(x=>(int?)x.Sequence)??0)+1;var item=new Problem{CaseId=caseId,WorkItemId=Input.WorkItemId,Sequence=seq,Category=Input.Category,Phenomenon=Input.Phenomenon.Trim(),OccurrenceCondition=Input.OccurrenceCondition?.Trim()??"",Impact=Input.Impact?.Trim()??"",CurrentWorkaround=Input.CurrentWorkaround?.Trim()??"",CauseHypothesis=Input.CauseHypothesis?.Trim()??"",Evidence=Input.Evidence?.Trim()??"",Severity=Input.Severity,Status=Input.Status,CreatedAt=now,UpdatedAt=now};database.Problems.Add(item);await database.SaveChangesAsync();if(item.WorkItemId is int workId)database.TraceLinks.Add(new TraceLink{CaseId=caseId,SourceType=TraceLinkTypes.WorkItem,SourceId=workId,TargetType=TraceLinkTypes.Problem,TargetId=item.Id,CreatedAt=now});Case.UpdatedAt=now;await database.SaveChangesAsync();return RedirectToPage("/Problems/Index",new{caseId});} private async Task<bool> Load(int caseId){var c=await database.Cases.SingleOrDefaultAsync(x=>x.Id==caseId);if(c is null)return false;Case=c;WorkItems=await database.WorkItems.Where(x=>x.CaseId==caseId).OrderBy(x=>x.Sequence).ToListAsync();return true;} public sealed class InputModel{[Display(Name="対象作業")]public int? WorkItemId{get;set;}[Required,Display(Name="分類")]public string Category{get;set;}=ProblemCategories.Other;[Required,Display(Name="現象・事実")]public string Phenomenon{get;set;}="";[Display(Name="発生条件・頻度")]public string? OccurrenceCondition{get;set;}[Display(Name="影響")]public string? Impact{get;set;}[Display(Name="現在の回避作業")]public string? CurrentWorkaround{get;set;}[Display(Name="原因仮説")]public string? CauseHypothesis{get;set;}[Display(Name="根拠")]public string? Evidence{get;set;}[Display(Name="重要度")]public string Severity{get;set;}=CasePriorities.Medium;[Display(Name="状態")]public string Status{get;set;}=ProblemStatuses.Confirming;}}
